const output = [];
const invoiceHints = /invoice|receipt|bill|statement/i;

for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) continue;

  for (const key of binaryKeys) {
    const bin = item.binary[key];
    if (!bin || bin.mimeType !== 'application/pdf') continue;

    const fileName = bin.fileName || '';
    const subject = item.json.subject || '';
    const looksLikeInvoice = invoiceHints.test(fileName) || invoiceHints.test(subject);
    if (!looksLikeInvoice) continue;

    output.push({
      json: {
        emailId: item.json.id,
        threadId: item.json.threadId,
        subject,
        from: item.json.from,
        attachmentFileName: fileName
      },
      binary: { data: bin }
    });
  }
}

return output;

const agentOut = $input.first().json.output;

if (!agentOut || agentOut.is_invoice !== true) {
  throw new Error('Document classified as NOT an invoice, or extraction failed.');
}

const required = ['vendor', 'invoice_number', 'total_amount', 'currency'];
for (const field of required) {
  const v = agentOut[field];
  if (v === null || v === undefined || v === '') {
    throw new Error('Missing required field "' + field + '" in extracted invoice data.');
  }
}

function sanitize(s) {
  return String(s).replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

const vendor = sanitize(agentOut.vendor);
const invoiceNumber = sanitize(agentOut.invoice_number);
const dateStr = agentOut.invoice_date ? sanitize(agentOut.invoice_date) : 'unknown_date';
const driveFileName = vendor + '_' + invoiceNumber + '_' + dateStr + '.pdf';

const source = $('Validate & Filter Attachments').first();

return [{
  json: {
    ...agentOut,
    vendor,
    invoice_number: invoiceNumber,
    driveFileName,
    emailId: source.json.emailId,
    sourceFileName: source.json.attachmentFileName
  },
  binary: source.binary
}];
